import hashlib
from collections import defaultdict
from pathlib import Path

def sha(p, buf=1<<20):
    h = hashlib.sha256()
    with open(p, 'rb') as f:
        for chunk in iter(lambda: f.read(buf), b''):
            h.update(chunk)
    return h.hexdigest()

buckets = defaultdict(list)
for p in Path('{{scan_dir}}').rglob('*'):
    if p.is_file():
        buckets[sha(p)].append(p)

for h, files in buckets.items():
    if len(files) > 1:
        print('DUP', h[:10])
        for f in files: print(' ', f)
